class NonCopyable {
public:
    NonCopyable() = default;
    ~NonCopyable() = default;

    NonCopyable(const NonCopyable&) = delete;
    NonCopyable& operator=(const NonCopyable&) = delete;
};

class ValueType {
public:
    ValueType() = default;
    ValueType(const ValueType&) = default;
    ValueType& operator=(const ValueType&) = default;

    // Disable move operations (optional)
    ValueType(ValueType&&) = delete;
    ValueType& operator=(ValueType&&) = delete;
};
